namespace MyFirstApp.Models
{
    public class Product
    {
        public int Id { get; set; }
        public string Name { get; set; } = string.Empty;
        public decimal Price { get; set; }
        public string Category { get; set; } = string.Empty;
        public DateTime CreatedAt { get; set; }
    }
}

using Microsoft.AspNetCore.Mvc;
using MyFirstApp.Models;

namespace MyFirstApp.Controllers
{
    public class ProductsController : Controller
    {
        // Simulated in-memory data for this example
        private static readonly List<Product> _products = new()
        {
            new Product { Id = 1, Name = "Laptop", Price = 999.99m, Category = "Electronics", CreatedAt = DateTime.Now },
            new Product { Id = 2, Name = "Coffee Mug", Price = 12.50m, Category = "Kitchen", CreatedAt = DateTime.Now }
        };

        public IActionResult Details(int id)
        {
            // Controller fetches data using the model
            var product = _products.FirstOrDefault(p => p.Id == id);

            if (product == null)
            {
                return NotFound();
            }

            // Passes the model to the view
            return View(product);
        }
    }
}
